172	  constructor(opts: MigratorOptions) {
173	    this.packageJson = opts.packageJson;
174	    this.nxInstallation = opts.nxInstallation;
175	    this.getInstalledPackageVersion = opts.getInstalledPackageVersion;
176	    this.fetch = opts.fetch;
177	    this.installedPkgVersionOverrides = opts.from;
178	    this.to = opts.to;
179	    this.interactive = opts.interactive;
180	    this.excludeAppliedMigrations = opts.excludeAppliedMigrations;
181	  }
