183	  async migrate(targetPackage: string, targetVersion: string) {
184	    await this.buildPackageJsonUpdates(targetPackage, {
185	      version: targetVersion,
186	      addToPackageJson: false,
187	    });
188	
189	    const migrations = await this.createMigrateJson();
190	    return {
191	      packageUpdates: this.packageUpdates,
192	      migrations,
193	      minVersionWithSkippedUpdates: this.minVersionWithSkippedUpdates,
194	    };
195	  }
