197	  private async createMigrateJson() {
198	    const migrations = await Promise.all(
199	      Object.keys(this.packageUpdates).map(async (packageName) => {
200	        if (this.packageUpdates[packageName].ignoreMigrations) {
201	          return [];
202	        }
203	
204	        const currentVersion = this.getPkgVersion(packageName);
205	        if (currentVersion === null) return [];
206	
207	        const { version } = this.packageUpdates[packageName];
208	        const { generators } = await this.fetch(packageName, version);
209	
210	        if (!generators) return [];
211	
212	        return Object.entries(generators)
213	          .filter(
214	            ([, migration]) =>
215	              migration.version &&
216	              this.gt(migration.version, currentVersion) &&
217	              this.lte(migration.version, version) &&
218	              this.areMigrationRequirementsMet(packageName, migration)
219	          )
220	          .map(([migrationName, migration]) => ({
221	            ...migration,
222	            package: packageName,
223	            name: migrationName,
224	          }));
225	      })
226	    );
227	
228	    return migrations.flat();
229	  }
