99	export function normalizeVersion(version: string) {
100	  const [semver, ...prereleaseTagParts] = version.split('-');
101	  // Handle versions like 1.0.0-beta-next.2
102	  const prereleaseTag = prereleaseTagParts.join('-');
103	
104	  const [major, minor, patch] = semver.split('.');
105	
106	  const newSemver = `${major || 0}.${minor || 0}.${patch || 0}`;
107	
108	  const newVersion = prereleaseTag
109	    ? `${newSemver}-${prereleaseTag}`
110	    : newSemver;
111	
112	  const withoutPatch = `${major || 0}.${minor || 0}.0`;
113	  const withoutPatchAndMinor = `${major || 0}.0.0`;
114	
115	  const variationsToCheck = [
116	    newVersion,
117	    newSemver,
118	    withoutPatch,
119	    withoutPatchAndMinor,
120	  ];
121	
122	  for (const variation of variationsToCheck) {
123	    try {
124	      if (gt(variation, '0.0.0')) {
125	        return variation;
126	      }
127	    } catch {}
128	  }
129	
130	  return '0.0.0';
131	}
